# PROVENANCE: copied from 06_paper_draft/figures/v11/fig2_casimir_shape.py on 2026-10-15 by fig-shape; restyled with
# style_v12; panel (b) now reads the slice generated by gen_casimir_slice_shape.py (same C57 Ewald sums); panel (c)
# adds the Standard Model with its zero-mode energy (f0 = 0.30) and at next order, and the guaranteed gain 6.72.
"""PRD figure prd_casimir_shape (Sec. IV and VII, label fig:pa-casimir-shape) - one conclusion: the Standard Model
supplies negative Casimir energy only with antiperiodic fermions, and that negative energy has no shape minimum: aspect
deformations run away and are amplified by hundreds through the turn.

(a) signed Casimir weight N_C of free high-energy SM content (+ static graviton) on the cubic torus at trivial holonomy
    for the spin-structure classes (C57). Filled: cube stationary by symmetry; open: not stationary.
(b) SM all-antiperiodic Casimir energy on the slice G = exp(2 b_d X_d + 2 b_a X_12) through the cube,
    Delta rho_C/|rho_C| (twisted Ewald sums; data/shape/casimir_slice_AAA.json); black line: no change.
(c) zero-incoming-momentum gain G(kappa) = sqrt2 cos(pi sqrt(1 - 4 kappa)/4) on the leading turning solution, with the
    aspect (E, orange) and angle (T2, blue) modes of the Maxwell toy (circles), the SM with free fields (open squares),
    with its zero-mode energy f0 = 0.30 (filled squares) and at next order (triangles). The sum rule
    sum kappa_A = 8/(1 - f0) forces some kappa >= 8/5 (free, shaded) or 8/(5(1 - f0)), hence gains >= 4.50 and 6.72.
Data: C57_spin_structures.json, casimir_slice_AAA.json, C63_results.json (toy and free-field stiffness),
C153_summary.json (f0 = 0.30 and next-order stiffness and gains), C76_summary.json (f0).
"""
from __future__ import annotations

import sys

import matplotlib.pyplot as plt
import numpy as np
from matplotlib.colors import LinearSegmentedColormap, TwoSlopeNorm

import style_v12 as st
import _helpers_shape as hs

st.use()
rows = st.load_json("shape/C57_spin_structures.json")["SM_spin_structures"]
SL = st.load_json("shape/casimir_slice_AAA.json")
C63 = st.load_json("shape/C63_results.json")
C153 = st.load_json("shape/C153_summary.json")
F0 = st.load_json("shape/C76_summary.json")["r"]
hs.check("slice N_C vs C57 AAA", SL["N_C_signed_check"], rows["AAA"]["N_C_signed"], 1e-4)


def gain(k):
    k = np.asarray(k, float)
    d = 1 - 4 * k
    return np.where(d >= 0, np.sqrt(2) * np.cos(np.pi / 4 * np.sqrt(np.abs(d))),
                    np.sqrt(2) * np.cosh(np.pi / 4 * np.sqrt(np.abs(d))))


fig = plt.figure(figsize=(st.DOUBLE, 2.35))
gs = fig.add_gridspec(1, 3, width_ratios=[0.78, 1.05, 1.12], wspace=0.62)
a, b, c = (fig.add_subplot(gs[0, i]) for i in range(3))

# (a) N_C by spin-structure class (P = periodic, A = antiperiodic fermions along each cycle) --------------------------
classes = [("PPP", True), ("PPA", False), ("PAA", False), ("AAA", True)]
xs = np.arange(len(classes))
for x, (key, stat) in zip(xs, classes):
    nc = rows[key]["N_C_signed"]
    a.plot([x, x], [0, nc], color=st.HAIR, lw=1.0, zorder=1)
    a.plot([x], [nc], "o", ms=5.5, mfc=st.INK if stat else st.SURFACE, mec=st.INK, mew=1.0, zorder=3)
    a.annotate(hs.fmt(nc, 1) if nc < 0 else f"+{nc:.1f}", (x, nc), xytext=(0, 6) if nc > 0 else (9, -3),
               textcoords="offset points", ha="center" if nc > 0 else "left", fontsize=7, color=st.INK2)
a.axhline(0, color=st.MUTED, lw=0.6)
a.set_xticks(xs)
a.set_xticklabels([k for k, _ in classes], fontsize=7)
a.set_xlim(-0.6, len(classes) - 0.4)
a.set_ylim(-40, 36)
a.yaxis.set_major_formatter(lambda v, p: hs.fmt(v, 0))
a.set_xlabel("fermion spin structure")
a.set_ylabel(r"signed Casimir weight $N_C$")
a.text(0.30, -13.0, "positive energy:\nno turning point", ha="left", va="center", fontsize=7, color=st.INK2)
a.text(1.35, -30.0, "open symbols:\ncube not\nstationary", ha="left", va="center", fontsize=7, color=st.MUTED)
a.tick_params(axis="x", length=0)
st.panel_label(a, "(a)", x=0.04, y=0.96)

# (b) SM-AAA landscape on the (b_d, b_a) slice -------------------------------------------------------------------------
BD, BA = np.meshgrid(SL["b_d"], SL["b_a"], indexing="xy")
drho = np.array(SL["drho"])
lim = np.max(np.abs(drho))
cmap = LinearSegmentedColormap.from_list("div", [st.DIV_NEG, st.DIV_MID, st.DIV_POS])
im = b.pcolormesh(BD, BA, drho, cmap=cmap, norm=TwoSlopeNorm(0, -lim, lim), shading="gouraud", rasterized=True)
b.contour(BD, BA, drho, levels=[0.0], colors=st.INK, linewidths=0.7)
b.set_xlabel(r"aspect $\beta_d$")
b.set_ylabel(r"angle $\beta_a$")
b.set_aspect("equal")
for ax_ in (b.xaxis, b.yaxis):
    ax_.set_major_formatter(lambda v, p: hs.fmt(v, 1) if abs(v) > 1e-9 else "0")
cb = fig.colorbar(im, ax=b, fraction=0.046, pad=0.03)
cb.set_label(r"$\Delta\rho_C/|\rho_C|$", fontsize=8)
cb.ax.tick_params(labelsize=7)
cb.ax.yaxis.set_major_formatter(lambda v, p: hs.fmt(v, 2) if abs(v) > 1e-9 else "0")
cb.outline.set_linewidth(0.5)
st.panel_label(b, "(b)", x=0.04, y=0.96)
b.text(0.95, 0.60, "SM, AAA", transform=b.transAxes, ha="right", va="center", fontsize=7, color=st.INK)

# (c) gain G(kappa), asinh scale ---------------------------------------------------------------------------------------
GT = C153["B_next_order"]["G_tables"]
fl = C153["B_next_order"]["floor_closed_form"]
kE30, kT30 = GT["E_xi030"]["kappa"], GT["T2_xi030"]["kappa"]
kEnx, kTnx = GT["E_next18.0"]["kappa"], GT["T2_next_rescaled"]["kappa"]
hs.check("gain(19.3237)", float(gain(kE30)), fl["19.3237"]["gain_calG_closed"], 1e-9)
hs.check("gain(18.0)", float(gain(kEnx)), fl["18.0"]["gain_calG_closed"], 1e-9)
toy, free = C63["NC100_toy"]["modes"], C63["SM_AAA"]["modes"]
k_min_free, k_min_f0 = 8 / 5, 8 / (5 * (1 - F0))
g_min_free, g_min_f0 = float(gain(k_min_free)), float(gain(k_min_f0))
kap = np.linspace(-10.0, 21.0, 1500)
c.axvspan(k_min_free, 21.0, color=st.GREY_FILL2, lw=0)
c.plot(kap, np.arcsinh(gain(kap)), color=st.INK2, lw=1.0)
c.axhline(np.arcsinh(g_min_free), color=st.MUTED, lw=0.6, ls=(0, (3, 2)))
c.axhline(np.arcsinh(g_min_f0), color=st.MUTED, lw=0.6, ls=(0, (1, 1.5)))
c.text(-8.8, np.arcsinh(g_min_f0) + 0.12, rf"$\mathcal{{G}}\geq{g_min_free:.2f}$" + "\n(free fields),\n"
       + rf"{g_min_f0:.2f} ($f_0=0.30$)", fontsize=7, color=st.INK2, va="bottom", linespacing=1.05)
c.text(10.5, np.arcsinh(1.6), r"shaded: $\kappa\geq8/5$", fontsize=7, color=st.INK2, va="center", ha="center")
pts = [  # kappa, colour, marker, filled
    (toy["aspect"]["kappa"], st.ORANGE, "o", True), (toy["angle"]["kappa"], st.BLUE, "o", True),
    (free["aspect"]["kappa"], st.ORANGE, "s", False), (free["angle"]["kappa"], st.BLUE, "s", False),
    (kE30, st.ORANGE, "s", True), (kT30, st.BLUE, "s", True),
    (kEnx, st.ORANGE, "^", True), (kTnx, st.BLUE, "^", True),
]
for k, col, m, filled in pts:
    c.plot([k], [np.arcsinh(gain(k))], m, ms=5.0, mfc=col if filled else st.SURFACE, mec=col if not filled else
           st.SURFACE, mew=1.0 if not filled else 0.6, zorder=5)
gE_free, gE30, gEnx = float(gain(free["aspect"]["kappa"])), float(gain(kE30)), float(gain(kEnx))
c.annotate(f"{gE30:.0f}", (kE30, np.arcsinh(gE30)), xytext=(-2, 7), textcoords="offset points",
           ha="center", va="bottom", fontsize=7, color=st.INK2)
c.annotate(f"{gEnx:.0f}", (kEnx, np.arcsinh(gEnx)), xytext=(0, -6), textcoords="offset points",
           ha="center", va="top", fontsize=7, color=st.INK2)
c.annotate(f"{gE_free:.0f}", (free["aspect"]["kappa"], np.arcsinh(gE_free)), xytext=(-7, 1),
           textcoords="offset points", ha="right", va="center", fontsize=7, color=st.INK2)
c.annotate(f"{float(gain(toy['aspect']['kappa'])):.1f}", (toy["aspect"]["kappa"],
           np.arcsinh(gain(toy["aspect"]["kappa"]))), xytext=(5, -3), textcoords="offset points", ha="left",
           va="top", fontsize=7, color=st.INK2)
c.text(9.0, np.arcsinh(gE_free) + 0.9, "aspect", fontsize=7, color=st.INK2, ha="center", va="bottom")
c.text(-5.0, np.arcsinh(0.45), "angle modes", ha="center", fontsize=7, color=st.INK2)
yt = np.array([-1, 0, 1, 10, 100, 1000])
c.set_yticks(np.arcsinh(yt))
c.set_yticklabels([str(v).replace("-", hs.MINUS) for v in yt])
c.xaxis.set_major_formatter(lambda v, p: hs.fmt(v, 0))
c.set_xlim(-10, 21)
c.set_ylim(np.arcsinh(-1.6), np.arcsinh(3000))
c.set_xlabel(r"normalized stiffness $\kappa=3\lambda/Z_{\rm eff}$")
c.set_ylabel(r"gain $\mathcal{G}=\beta_+/\beta_-$")
h = [c.plot([], [], "o", color=st.INK2, ms=4.5, label="Maxwell toy")[0],
     c.plot([], [], "s", mfc=st.SURFACE, mec=st.INK2, ms=4.5, label="SM, free fields")[0],
     c.plot([], [], "s", color=st.INK2, ms=4.5, label=r"SM, $f_0=0.30$")[0],
     c.plot([], [], "^", color=st.INK2, ms=4.5, label="SM, next order")[0]]
c.legend(handles=h, loc="upper left", bbox_to_anchor=(0.0, 0.89), fontsize=7, borderaxespad=0.3,
         handletextpad=0.3, labelspacing=0.25)
st.panel_label(c, "(c)", x=0.04, y=0.96)

print(f"gains: free {gE_free:.2f}, f0=0.30 {gE30:.2f}, next {gEnx:.2f}; angle f0=0.30 {float(gain(kT30)):.3f}, "
      f"next {float(gain(kTnx)):.3f}; guaranteed {g_min_free:.6f}/{g_min_f0:.3f} at kappa {k_min_free}/{k_min_f0:.4f}")
if __name__ == "__main__":
    sys.stdout.reconfigure(encoding="utf-8")
    print(st.save(fig, "prd_casimir_shape", width=st.DOUBLE, papers=("prd",)))
